// src/components/layout/Sidebar.jsx
import C from "../../constants/colors";
import NavItem from "../ui/NavItem";
import i18n from "../../i18n";

const NAV_ITEMS = [
  { id: "dashboard", icon: "🏠",  label: "Dashboard"      },
  { id: "bot",       icon: "🤖",  label: "AI Agro Bot"    },
  { id: "disease",   icon: "🔬",  label: "Disease Detect" },
  { id: "map",       icon: "🗺️",  label: "Farm Map"       },
  { id: "market",    icon: "📈",  label: "Market Prices"  },
  { id: "community", icon: "👥",  label: "Community", badge: 3 },
  { id: "schemes",   icon: "🏛️",  label: "Gov Schemes"    },
  { id: "shops",     icon: "🏪",  label: "Agri Shops"     },
  { id: "profile",   icon: "👤",  label: "Profile"        },
];

export default function Sidebar({ user, page, setPage }) {
  return (
    <div style={{
      width:          210,
      minHeight:      "100vh",
      height:         "100vh",
      background:     C.dark,
      display:        "flex",
      flexDirection:  "column",
      padding:        "0 8px",
      flexShrink:     0,
      position:       "sticky",
      top:            0,
      overflowY:      "auto",
    }}>

      <div style={{ padding: '20px', borderTop: '1px solid #eee' }}>
  <select 
    onChange={(e) => {
  console.log("Changing language to:", e.target.value); // Idhai add pannunga
  i18n.changeLanguage(e.target.value);
}}
    style={{
      width: '100%',
      padding: '8px',
      borderRadius: '8px',
      border: '1px solid #ddd',
      background: 'white',
      fontWeight: 'bold',
      color: '#059669' // Green color
    }}
  >
    <option value="en">English</option>
    <option value="ta">தமிழ்</option>
    <option value="hi">हिंदी</option>
  </select>
</div>

      {/* ── Logo ─────────────────────────────────────────── */}
      <div style={{
        padding:      "16px 6px 12px",
        borderBottom: "1px solid rgba(255,255,255,0.07)",
        marginBottom: 8,
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          {/* Icon box */}
          <div style={{
            width:          36,
            height:         36,
            borderRadius:   9,
            background:     C.bg2,
            display:        "flex",
            alignItems:     "center",
            justifyContent: "center",
            fontSize:       18,
            flexShrink:     0,
          }}>
            🌿
          </div>

          {/* Brand text */}
          <div>
            <div style={{
              color:          "#fff",
              fontWeight:     700,
              fontSize:       14.5,
              letterSpacing:  "-0.02em",
              lineHeight:     1.2,
            }}>
              Agro Zenith
            </div>
            <div style={{ color: "rgba(255,255,255,0.4)", fontSize: 10 }}>
              Empowering Agriculture
            </div>
          </div>
        </div>
      </div>

      {/* ── Navigation ───────────────────────────────────── */}
      <div style={{
        flex:          1,
        display:       "flex",
        flexDirection: "column",
        gap:           1,
      }}>
        {NAV_ITEMS.map(n => (
          <NavItem
            key={n.id}
            {...n}
            active={page === n.id}
            onClick={setPage}
          />
        ))}
      </div>

      {/* ── User footer ──────────────────────────────────── */}
      <div style={{
        padding:    "10px 6px 14px",
        borderTop:  "1px solid rgba(255,255,255,0.07)",
        marginTop:  6,
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 7 }}>

          {/* Avatar */}
          <div style={{
            width:          30,
            height:         30,
            borderRadius:   "50%",
            background:     C.bg2,
            display:        "flex",
            alignItems:     "center",
            justifyContent: "center",
            color:          "#fff",
            fontSize:       11,
            fontWeight:     700,
            flexShrink:     0,
          }}>
            {user.name.slice(0, 2).toUpperCase()}
          </div>

          {/* Name + district */}
          <div style={{ overflow: "hidden" }}>
            <div style={{
              color:        "#fff",
              fontSize:     12,
              fontWeight:   500,
              whiteSpace:   "nowrap",
              overflow:     "hidden",
              textOverflow: "ellipsis",
            }}>
              {user.name.split(" ")[0]}
            </div>
            <div style={{
              color:        "rgba(255,255,255,0.38)",
              fontSize:     10,
              whiteSpace:   "nowrap",
              overflow:     "hidden",
              textOverflow: "ellipsis",
            }}>
              {user.district}
            </div>
          </div>

        </div>
      </div>

    </div>
  );
}
